const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helper to wrap getInfo in a Promise
  const getInfo = (eeObj) => new Promise((resolve, reject) => eeObj.getInfo(resolve, reject));

  // 1. Geometry & Time Definitions (Central Kalahari Desert area)
  const geom = ee.Geometry.Polygon([
    [22.0, -22.0],
    [24.5, -22.0],
    [24.5, -24.5],
    [22.0, -24.5],
    [22.0, -22.0]
  ]);

  const targetA = '2008-08-06';
  const targetB = '2009-04-19';

  // 2. Collections and masking
  function mergedL57(geometry) {
    return ee.ImageCollection('LANDSAT/LT05/C02/T1_L2').filterBounds(geometry)
      .merge(ee.ImageCollection('LANDSAT/LT05/C02/T2_L2').filterBounds(geometry))
      .merge(ee.ImageCollection('LANDSAT/LE07/C02/T1_L2').filterBounds(geometry))
      .merge(ee.ImageCollection('LANDSAT/LE07/C02/T2_L2').filterBounds(geometry));
  }

  function maskL57L2(image) {
    const qa = image.select('QA_PIXEL');
    // Keep pixels that are not cloud, not cloud shadow, not snow, not dilated cloud, not cirrus.
    const mask = qa.bitwiseAnd(1 << 1).eq(0) // Dilated Cloud
      .and(qa.bitwiseAnd(1 << 3).eq(0))      // Cloud Shadow
      .and(qa.bitwiseAnd(1 << 4).eq(0))      // Snow
      .and(qa.bitwiseAnd(1 << 5).eq(0))      // Cloud
      .and(qa.bitwiseAnd(1 << 7).eq(0));     // Cirrus
    return image.updateMask(mask);
  }

  async function getStatsForDate(dateStr) {
    const date = ee.Date(dateStr);
    const colAll = mergedL57(geom);

    // Candidate counts for evidence
    const col1d = colAll.filterDate(date, date.advance(1, 'day'));
    const col14d = colAll.filterDate(date.advance(-7, 'day'), date.advance(8, 'day'));
    const col30d = colAll.filterDate(date.advance(-30, 'day'), date.advance(31, 'day'));
    const n1 = await getInfo(col1d.size());
    const n14 = await getInfo(col14d.size());
    const n30 = await getInfo(col30d.size());

    let workingCol = null;
    if (n1 > 0) workingCol = col1d;
    else if (n14 > 0) workingCol = col14d;
    else if (n30 > 0) workingCol = col30d;
    else {
      return {
        status: 'C1',
        counts: { n1, n14, n30 }
      };
    }

    // Choose the closest in time, then lowest cloud cover
    const withDelta = workingCol.map(function (img) {
      const deltaDays = ee.Number(img.date().difference(date, 'day')).abs();
      const cloud = ee.Number(ee.Algorithms.If(img.get('CLOUD_COVER'), ee.Number(img.get('CLOUD_COVER')), 100));
      const sortKey = deltaDays.multiply(1000).add(cloud);
      return img.set({ deltaDays, sortKey });
    }).sort('sortKey');

    const img = ee.Image(withDelta.first());
    const imgDateStr = await getInfo(ee.Date(img.get('system:time_start')).format('YYYY-MM-dd'));
    const cloudCover = await getInfo(img.get('CLOUD_COVER'));
    const spacecraft = await getInfo(img.get('SPACECRAFT_ID'));
    const productId = await getInfo(img.get('LANDSAT_PRODUCT_ID'));
    const sensorLabel = spacecraft || (productId ? String(productId).slice(0, 4) : 'L57');

    // Compute NDVI with masking
    const masked = maskL57L2(img);
    const srScaled = img.select(['SR_B3', 'SR_B4']).multiply(0.0000275).add(-0.2);
    const ndvi = srScaled.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI')
      .updateMask(masked.mask());

    // Pixel counts
    const totalCount = await getInfo(srScaled.select('SR_B3').reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: 1000,
      maxPixels: 1e9
    }).get('SR_B3'));
    const validCount = await getInfo(ndvi.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geom,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDVI'));

    if (!totalCount || totalCount === 0) {
      return {
        status: 'C2',
        counts: { n1, n14, n30 },
        chosen: { date: imgDateStr, sensor: sensorLabel, cloud: cloudCover || null, valid: 0, total: 0, ndvi: null }
      };
    }
    if (!validCount || validCount === 0) {
      return {
        status: 'C2',
        counts: { n1, n14, n30 },
        chosen: { date: imgDateStr, sensor: sensorLabel, cloud: cloudCover || null, valid: 0, total: totalCount, ndvi: null }
      };
    }

    const meanNdvi = await getInfo(ndvi.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: geom,
      scale: 1000,
      maxPixels: 1e9
    }).get('NDVI'));

    if (meanNdvi === null || meanNdvi === undefined || !isFinite(meanNdvi) || meanNdvi < -1.0 || meanNdvi > 1.0) {
      return {
        status: 'C3',
        counts: { n1, n14, n30 },
        chosen: { date: imgDateStr, sensor: sensorLabel, cloud: cloudCover || null, valid: validCount, total: totalCount, ndvi: meanNdvi }
      };
    }

    return {
      status: 'OK',
      counts: { n1, n14, n30 },
      chosen: {
        date: imgDateStr,
        sensor: sensorLabel,
        cloud: cloudCover || 0,
        valid: validCount,
        total: totalCount,
        ndvi: meanNdvi
      }
    };
  }

  try {
    const resA = await getStatsForDate(targetA);
    const resB = await getStatsForDate(targetB);

    // Print concise evidence
    console.log(`${targetA} candidates: 1d=${resA.counts.n1}, ±7d=${resA.counts.n14}, ±30d=${resA.counts.n30}`);
    if (resA.status === 'OK') {
      console.log(`Chosen ${resA.chosen.date} ${resA.chosen.sensor} CC=${(+resA.chosen.cloud).toFixed(1)}% Valid=${resA.chosen.valid}/${resA.chosen.total} NDVI=${resA.chosen.ndvi.toFixed(3)}`);
    } else {
      console.log(`Chosen none (status ${resA.status})`);
    }

    console.log(`${targetB} candidates: 1d=${resB.counts.n1}, ±7d=${resB.counts.n14}, ±30d=${resB.counts.n30}`);
    if (resB.status === 'OK') {
      console.log(`Chosen ${resB.chosen.date} ${resB.chosen.sensor} CC=${(+resB.chosen.cloud).toFixed(1)}% Valid=${resB.chosen.valid}/${resB.chosen.total} NDVI=${resB.chosen.ndvi.toFixed(3)}`);
    } else {
      console.log(`Chosen none (status ${resB.status})`);
    }

    // Final tag decision with error precedence
    if (resA.status === 'C1' || resB.status === 'C1') {
      console.log('C1');
      return;
    }
    if (resA.status === 'C2' || resB.status === 'C2') {
      console.log('C2');
      return;
    }
    if (resA.status === 'C3' || resB.status === 'C3') {
      console.log('C3');
      return;
    }

    // Compare NDVI means
    const ndviA = resA.chosen.ndvi;
    const ndviB = resB.chosen.ndvi;
    if (ndviB > ndviA) {
      console.log('A'); // Yes
    } else {
      console.log('B'); // No
    }
  } catch (err) {
    console.log(`Error: ${err && err.message ? err.message : err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
